		String previousStartup = System.getProperty("rdf4j.lmdb.parallel.startupWork");
		try {
			System.setProperty("rdf4j.lmdb.parallel.threads", "64");
			System.setProperty("rdf4j.lmdb.parallel.minWorkEstimate", "0");
			System.setProperty("rdf4j.lmdb.parallel.startupWork", "0");
			FixtureNodePredicates predicates = new FixtureNodePredicates().meanPredicateDegree(1D);
			long[] roots = sequence(1L, 100);
			for (long root : roots) {
				predicates.row(root, new long[] { 1L }, new long[] { 100L + root });
			}

			assertThat(LmdbNodePredicateRoute.tryBuild(predicates, roots, roots.length, 64,
					1L << 20, 0.25D)).isNull();
			assertThat(predicates.findCalls)
					.as("route admission must compare against the available parallel predicate sweep")
					.isEmpty();
		} finally {
			restoreProperty("rdf4j.lmdb.parallel.threads", previousThreads);
			restoreProperty("rdf4j.lmdb.parallel.minWorkEstimate", previousThreshold);
			restoreProperty("rdf4j.lmdb.parallel.startupWork", previousStartup);
		}
