	private static void assertGroup(LmdbNodePredicateRoute route, int group, long predicate, int[] roots,
			long[] runs) {
		assertThat(route.predicateAt(group)).isEqualTo(predicate);
		int from = route.predicateFrom(group);
		int to = route.predicateTo(group);
		int[] actualRoots = new int[to - from];
		long[] actualRuns = new long[to - from];
		for (int i = from; i < to; i++) {
			actualRoots[i - from] = route.rootOrdinalAt(i);
			actualRuns[i - from] = route.runReferenceAt(i);
		}
		assertThat(actualRoots).containsExactly(roots);
		assertThat(actualRuns).containsExactly(runs);
	}

	private static long[] sequence(long first, int length) {
		long[] values = new long[length];
		for (int i = 0; i < length; i++) {
			values[i] = first + i;
		}
		return values;
	}

	private static NativeSlotLayout layout(String... names) {
		Map<String, Integer> slots = new LinkedHashMap<>();
		for (int slot = 0; slot < names.length; slot++) {
			slots.put(names[slot], slot);
		}
		NativeSlotLayout layout = new NativeSlotLayout(slots, null);
		layout.freeze(List.of(names));
		return layout;
	}

	private static void restoreProperty(String name, String value) {
		if (value == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, value);
		}
	}

	private static final class FixtureNodePredicates implements NativeLmdbQuerySource.NodePredicates {
		private final Map<Long, Row> rows = new LinkedHashMap<>();
		private final Map<Long, Integer> findCalls = new LinkedHashMap<>();
		private int rowSizeCalls;
		private int totalFindCalls;
		private int interruptOnFind = -1;
		private double meanPredicateDegree = Double.NaN;

		FixtureNodePredicates row(long root, long[] predicates, long[] runs) {
			rows.put(root, new Row(predicates, runs));
			return this;
		}

		FixtureNodePredicates interruptOnFind(int call) {
			interruptOnFind = call;
			return this;
		}

		FixtureNodePredicates meanPredicateDegree(double value) {
			meanPredicateDegree = value;
			return this;
		}

		@Override
		public long find(long node) {
			findCalls.merge(node, 1, Integer::sum);
			if (++totalFindCalls == interruptOnFind) {
				Thread.currentThread().interrupt();
			}
			return rows.containsKey(node) ? node : NOT_FOUND;
		}

		@Override
		public long rowSize(long rowHandle) {
			rowSizeCalls++;
			return rows.get(rowHandle).predicates.length;
		}

		@Override
		public int copyRow(long node, long rowHandle, long fromOffset, int length, long[] predicateTarget,
				int predicateOffset, long[] runTarget, int runOffset) {
			Row row = rows.get(rowHandle);
			int copied = Math.min(length, row.predicates.length - Math.toIntExact(fromOffset));
			System.arraycopy(row.predicates, Math.toIntExact(fromOffset), predicateTarget, predicateOffset, copied);
			System.arraycopy(row.runs, Math.toIntExact(fromOffset), runTarget, runOffset, copied);
			return copied;
		}

		@Override
		public double meanPredicateDegree() {
			return meanPredicateDegree;
		}

		@Override
		public long size(long runHandle) {
			return 1L;
		}

		@Override
		public long neighborAt(long runHandle, long runOffset) {
			return runHandle;
		}

		@Override
		public long contextAt(long runHandle, long runOffset) {
			return 0L;
		}

		private record Row(long[] predicates, long[] runs) {
			private Row {
				if (predicates.length != runs.length) {
					throw new IllegalArgumentException("misaligned fixture row");
				}
				predicates = Arrays.copyOf(predicates, predicates.length);
				runs = Arrays.copyOf(runs, runs.length);
			}
		}
	}

